// ItemMetadataUpdate The fields the administrator changes (since contract 1.15.0); a field left out stays as it is. Texts
// belong to the server's metadata language. `""` clears `originalTitle`, `releaseDate`, `tagline` and
// `overview`; an empty `genres` list clears the genres of that language.
type ItemMetadataUpdate struct {
	// Asin Audiobooks only (since 1.24.0); ten letters or digits, or `""`.
	Asin *string `json:"asin,omitempty"`

	// Author Audiobooks only (since 1.24.0); several names separated by commas, as the files give them.
	Author *string   `json:"author,omitempty"`
	Genres *[]string `json:"genres,omitempty"`

	// Isbn Audiobooks only (since 1.24.0); 10 or 13 digits, hyphens and spaces allowed, or `""`.
	Isbn *string `json:"isbn,omitempty"`

	// Narrator Audiobooks only (since 1.24.0).
	Narrator      *string `json:"narrator,omitempty"`
	OriginalTitle *string `json:"originalTitle,omitempty"`
	Overview      *string `json:"overview,omitempty"`

	// Publisher Audiobooks only (since 1.24.0).
	Publisher *string `json:"publisher,omitempty"`

	// ReleaseDate `YYYY-MM-DD` or `""`.
	ReleaseDate *string `json:"releaseDate,omitempty"`

	// SeriesIndex Audiobooks only (since 1.24.0); the volume in the series, `0.5` before `1`.
	SeriesIndex *float64 `json:"seriesIndex,omitempty"`

	// SeriesName Audiobooks only (since 1.24.0); `""` clears the series and the volume.
	SeriesName *string `json:"seriesName,omitempty"`
	SortTitle  *string `json:"sortTitle,omitempty"`
	Tagline    *string `json:"tagline,omitempty"`
	Title      *string `json:"title,omitempty"`

	// Unlock Fields whose lock goes; for a text field its lock in the server language and an old lock without language, which the other languages with a stored text keep as their own lock (`title:<lang>`), so only the server language is freed. For an audiobook a text field is freed in every text row of the book.
	Unlock *[]AdminMetadataField `json:"unlock,omitempty"`
	Year   *int                  `json:"year,omitempty"`
}

